import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { scoutNamesBySkill } from '@posthog/agent-contracts/scout-names'

import { ApiError } from 'lib/api-error'
import { teamLogic } from 'scenes/teamLogic'

import { signalsScoutConfigList } from 'products/signals/frontend/generated/api'
import type { SignalScoutConfigApi } from 'products/signals/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutNamesLogicValues {
    currentTeamId: number | null // teamLogic
    scoutConfigs: SignalScoutConfigApi[] | null
    scoutConfigsLoading: boolean
    scoutNamesBySkill: Record<string, string>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutNamesLogicActions {
    loadScoutConfigs: () => any
    loadScoutConfigsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadScoutConfigsSuccess: (
        scoutConfigs: SignalScoutConfigApi[] | null,
        payload?: any
    ) => {
        scoutConfigs: SignalScoutConfigApi[] | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutNamesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        scoutNamesBySkill: (scoutConfigs: SignalScoutConfigApi[] | null) => Record<string, string>
    }
}

export type scoutNamesLogicType = MakeLogicType<
    scoutNamesLogicValues,
    scoutNamesLogicActions,
    Record<string, any>,
    scoutNamesLogicMeta
>

/**
 * Scout display names for surfaces outside the inbox, such as the Today home.
 * `scoutFleetLogic` also exposes these names, but it pulls the whole fleet UI onto the importer's eager bundle.
 */
export const scoutNamesLogic = kea<scoutNamesLogicType>([
    path(['products', 'signals', 'frontend', 'inbox', 'logics', 'scoutNamesLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        scoutConfigs: [
            null as SignalScoutConfigApi[] | null,
            {
                loadScoutConfigs: async (): Promise<SignalScoutConfigApi[] | null> => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    try {
                        return await signalsScoutConfigList(String(values.currentTeamId))
                    } catch (error) {
                        // Without scout access the names fall back to prettified skill names.
                        if (error instanceof ApiError && (error.status === 403 || error.status === 404)) {
                            return null
                        }
                        throw error
                    }
                },
            },
        ],
    })),
    selectors({
        scoutNamesBySkill: [
            (s) => [s.scoutConfigs],
            (scoutConfigs: SignalScoutConfigApi[] | null): Record<string, string> => scoutNamesBySkill(scoutConfigs),
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadScoutConfigs()
    }),
])
